package com.example.defaultproject.player

import android.content.Context
import androidx.media3.common.MediaItem
import androidx.media3.common.Player
import androidx.media3.exoplayer.ExoPlayer
import com.example.defaultproject.data.Song

object PlayerManager {

    private var player: ExoPlayer? = null
    var playlist: List<Song> = emptyList()
        private set
    var currentIndex: Int = -1
        private set

    fun get(context: Context): ExoPlayer {
        return player ?: ExoPlayer.Builder(context.applicationContext).build().also {
            it.repeatMode = Player.REPEAT_MODE_ALL
            player = it
        }
    }

    fun existing(): ExoPlayer? = player

    fun setPlaylist(context: Context, songs: List<Song>, startIndex: Int) {
        if (songs.isEmpty()) return
        playlist = songs
        currentIndex = startIndex.coerceIn(0, songs.lastIndex)
        val p = get(context)
        p.clearMediaItems()
        songs.forEach { p.addMediaItem(MediaItem.fromUri(it.uri)) }
        p.prepare()
        p.seekTo(currentIndex, 0L)
        p.playWhenReady = true
    }

    fun currentSong(): Song? = playlist.getOrNull(currentIndex)

    fun syncIndex() {
        val p = player ?: return
        if (playlist.isEmpty()) return
        val idx = p.currentMediaItemIndex
        if (idx in playlist.indices) currentIndex = idx
    }

    fun playPause() {
        player?.let { if (it.isPlaying) it.pause() else it.play() }
    }

    fun next(context: Context) {
        if (playlist.isEmpty()) return
        val p = get(context)
        if (p.hasNextMediaItem()) p.seekToNextMediaItem() else p.seekTo(0, 0L)
        p.play()
    }

    fun previous(context: Context) {
        if (playlist.isEmpty()) return
        val p = get(context)
        if (p.currentPosition > 3000) {
            p.seekTo(0)
        } else if (p.hasPreviousMediaItem()) {
            p.seekToPreviousMediaItem()
        } else {
            p.seekTo(playlist.lastIndex, 0L)
        }

